<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model { protected $fillable=['order_number','customer_id','farmer_id','market_id','pickup_date','pickup_slot','status','total_amount','notes','placed_at']; protected $casts=['pickup_date'=>'date','total_amount'=>'decimal:2','placed_at'=>'datetime']; public function customer(){return $this->belongsTo(User::class,'customer_id');} public function farmer(){return $this->belongsTo(User::class,'farmer_id');} public function market(){return $this->belongsTo(Market::class);} public function items(){return $this->hasMany(OrderItem::class);} }
